import numpy as np

def to_float_array(values):
    return np.array(values, dtype=float)

import numpy as np

def to_bool_array(values):
    return np.array(values, dtype=bool)

import numpy as np

def column(grid, i):
    return np.array(grid)[:, i].tolist()

import numpy as np

def top_left(grid, n):
    return np.array(grid)[0:n, 0:n].tolist()

import numpy as np

def column_means(grid):
    return np.array(grid).mean(axis=0).tolist()

import numpy as np

def row_totals(grid):
    return np.array(grid).sum(axis=1).tolist()
